// A brief the server generated carries a proof: HMAC-SHA256 over its content, bound to the tenant and
// the person it was generated for. Saving needs the proof back, so a client cannot store claims the
// processor never produced under the label "Generated by Anthropic API" (L-04). The key is
// INTERNAL_HMAC_KEY with a fixed context string, so the proof cannot be replayed as any signed call.

const CONTEXT = "secondary-brief-proof-v1";
const MAX_AGE_MS = 24 * 3_600_000;
const SKEW_MS = 5 * 60_000;

/** Stable JSON: keys sorted at every level. */
const canonical = (v: unknown): string =>
  JSON.stringify(v, (_k, x: unknown) =>
    x && typeof x === "object" && !Array.isArray(x)
      ? Object.fromEntries(Object.entries(x).sort(([a], [b]) => a.localeCompare(b)))
      : x,
  );

type Signed = {
  target?: unknown;
  title?: unknown;
  sections?: unknown;
  evidence?: unknown;
  disclosure?: { model?: unknown; generatedAt?: unknown } | null;
};

/** The fields a proof covers. Evidence is reduced to ids and node ids; titles are re-read from the view on save. */
const material = (tenantId: string, principalId: string, b: Signed): string => {
  const t = (b.target ?? {}) as Record<string, unknown>;
  const ev = Array.isArray(b.evidence) ? (b.evidence as Record<string, unknown>[]) : [];
  return canonical({
    context: CONTEXT,
    tenantId,
    principalId,
    target: {
      accountId: t.accountId ?? null,
      nodeId: t.nodeId ?? null,
      meetingId: t.meetingId ?? null,
    },
    title: b.title,
    sections: b.sections,
    evidence: ev.map((e) => ({ id: e.id, nodeId: e.nodeId })),
    model: b.disclosure?.model,
    generatedAt: b.disclosure?.generatedAt,
  });
};

const hex = (b: ArrayBuffer): string =>
  [...new Uint8Array(b)].map((x) => x.toString(16).padStart(2, "0")).join("");

async function mac(secret: string, text: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  return hex(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(text)));
}

/** Null when no key is configured: nothing can then be saved from the client. */
export async function briefProof(
  env: { INTERNAL_HMAC_KEY?: string },
  tenantId: string,
  principalId: string,
  brief: Signed,
): Promise<string | null> {
  const k = env.INTERNAL_HMAC_KEY;
  if (!k || k.length < 32) return null;
  return mac(k, material(tenantId, principalId, brief));
}

export async function briefProofValid(
  env: { INTERNAL_HMAC_KEY?: string },
  tenantId: string,
  principalId: string,
  brief: Signed,
  proof: unknown,
  now: number,
): Promise<boolean> {
  if (typeof proof !== "string" || !/^[0-9a-f]{64}$/.test(proof)) return false;
  const expected = await briefProof(env, tenantId, principalId, brief);
  if (!expected) return false;
  let diff = 0;
  for (let i = 0; i < 64; i++) diff |= expected.charCodeAt(i) ^ proof.charCodeAt(i);
  if (diff !== 0) return false;
  const at = Date.parse(String(brief.disclosure?.generatedAt ?? ""));
  return Number.isFinite(at) && at <= now + SKEW_MS && now - at <= MAX_AGE_MS;
}
